"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["9133"],{20989(e){e.exports=JSON.parse('{"id":"FIN-173","slug":"cost-of-debt","term":"Cost of Debt","also_known_as":[],"difficulty":"Beginner","definition":"The cost of debt is the effective interest rate a company pays on the money it borrows, through loans and bonds.","explanation":["When a company borrows, lenders charge interest to compensate for the time value of money and the risk of not being repaid. The cost of debt is the overall rate the company pays on its borrowing.","For a company with a single loan at 6%, the cost of debt is simply 6%. For a company with several loans and bonds, it is a weighted average of their rates. Analysts often use the current yield on the company\'s bonds, or the rate it would pay on new borrowing, because that reflects today\'s market conditions better than old loan rates.","The cost of debt depends mainly on the company\'s credit risk and on general interest rates. A financially strong company with a high credit rating borrows more cheaply than a weaker one. When central banks raise rates, borrowing costs for all companies tend to rise.","Debt is usually cheaper than equity, because lenders are paid before shareholders and take less risk. In many tax systems, interest is also deductible from taxable profit, which lowers the effective cost further. That adjusted figure is called the after-tax cost of debt."],"note":"","total":1500,"prev":{"slug":"cost-of-capital","term":"Cost of Capital"},"next":{"slug":"cost-of-equity","term":"Cost of Equity"}}')}}]);